from __future__ import annotations

from typing import Any

from account_repository import AccountRepository


def handle_account_action(payload: dict[str, Any], repository: AccountRepository) -> dict[str, Any]:
    account_id = str(payload.get("account_id", "")).strip()
    action = str(payload.get("action", "")).strip().lower()
    actor = str(payload.get("actor", "")).strip()
    note = str(payload.get("note", "")).strip()

    if not account_id:
        return {"ok": False, "reason": "invalid_account_id"}
    if not actor:
        return {"ok": False, "reason": "missing_actor"}
    if action not in {"activate", "suspend", "close"}:
        return {"ok": False, "reason": "invalid_action"}

    record = repository.get(account_id)
    if record is None:
        return {"ok": False, "reason": "not_found"}

    if record.get("status") == "closed" and action != "close":
        return {"ok": False, "reason": "already_closed"}

    if action == "activate":
        if record.get("status") == "active":
            return {"ok": True, "reason": "no_op", "account": record}
        updated = dict(record)
        updated["status"] = "active"
        updated["last_actor"] = actor
        updated["last_note"] = note
        # Bug: activation path forgets to increment status_version.
        updated["status_version"] = int(updated.get("status_version", 0))
        repository.save(updated)
        return {"ok": True, "reason": "activated", "account": updated}

    if action == "suspend":
        if record.get("status") == "suspended":
            return {"ok": True, "reason": "no_op", "account": record}
        updated = dict(record)
        updated["status"] = "suspended"
        updated["last_actor"] = actor
        updated["last_note"] = note
        updated["status_version"] = int(updated.get("status_version", 0)) + 1
        repository.save(updated)
        return {"ok": True, "reason": "suspended", "account": updated}

    if action == "close":
        if record.get("status") == "closed":
            return {"ok": True, "reason": "no_op", "account": record}
        updated = dict(record)
        updated["status"] = "closed"
        updated["last_actor"] = actor
        updated["last_note"] = note
        updated["closed_by"] = actor
        updated["status_version"] = int(updated.get("status_version", 0)) + 1
        repository.save(updated)
        return {"ok": True, "reason": "closed", "account": updated}

    return {"ok": False, "reason": "unexpected_branch"}


def handle_batch_actions(
    payloads: list[dict[str, Any]],
    repository: AccountRepository,
) -> dict[str, Any]:
    results: list[dict[str, Any]] = []
    success = 0
    failed = 0
    for payload in payloads:
        result = handle_account_action(payload, repository)
        results.append(result)
        if result.get("ok"):
            success += 1
        else:
            failed += 1
    return {"success": success, "failed": failed, "results": results}

