from typing import Any


class AccountRepository:
    def __init__(self) -> None:
        self._records: dict[str, dict[str, Any]] = {}

    def seed(self, items: list[dict[str, Any]]) -> None:
        self._records.clear()
        for item in items:
            account_id = str(item.get("account_id", "")).strip()
            if not account_id:
                raise ValueError("account_id is required")
            status = str(item.get("status", "active")).strip().lower() or "active"
            if status not in {"active", "suspended", "closed"}:
                raise ValueError("invalid status")
            self._records[account_id] = {
                "account_id": account_id,
                "status": status,
                "status_version": int(item.get("status_version", 1)),
                "last_actor": str(item.get("last_actor", "")).strip(),
                "last_note": str(item.get("last_note", "")).strip(),
                "closed_by": str(item.get("closed_by", "")).strip(),
            }

    def get(self, account_id: str) -> dict[str, Any] | None:
        key = account_id.strip()
        if not key:
            return None
        item = self._records.get(key)
        if item is None:
            return None
        return dict(item)

    def save(self, record: dict[str, Any]) -> None:
        account_id = str(record.get("account_id", "")).strip()
        if not account_id:
            raise ValueError("account_id is required")
        status = str(record.get("status", "")).strip().lower()
        if status not in {"active", "suspended", "closed"}:
            raise ValueError("invalid status")
        self._records[account_id] = {
            "account_id": account_id,
            "status": status,
            "status_version": int(record.get("status_version", 1)),
            "last_actor": str(record.get("last_actor", "")).strip(),
            "last_note": str(record.get("last_note", "")).strip(),
            "closed_by": str(record.get("closed_by", "")).strip(),
        }

    def exists(self, account_id: str) -> bool:
        key = account_id.strip()
        return bool(key) and key in self._records

    def count(self) -> int:
        return len(self._records)

    def list_ids(self) -> list[str]:
        return sorted(self._records.keys())

    def snapshot(self) -> dict[str, dict[str, Any]]:
        return {key: dict(value) for key, value in self._records.items()}

    def clear(self) -> None:
        self._records.clear()

